import * as crypto from 'node:crypto';
async function main(): Promise<void> {
  const c: any = crypto;
  console.log(c.checkPrimeSync(Buffer.from([7])), c.checkPrimeSync(Buffer.from([8])), c.checkPrimeSync(Buffer.from([0x01, 0x01])), c.checkPrimeSync(Buffer.from('1fffffffffffffff', 'hex'), { checks: 5 }));
  console.log(await new Promise<any>((r) => c.checkPrime(Buffer.from([13]), (e: any, ok: boolean) => r([e, ok]))));
  const ab: any = c.generatePrimeSync(48);
  const hex: string = Buffer.from(ab).toString('hex');
  console.log(typeof ab, ab.byteLength, c.checkPrimeSync(ab), parseInt(hex.slice(0, 2), 16) >= 128 || parseInt(hex.slice(0, 2), 16) >= 0);
  const sp: any = c.generatePrimeSync(32, { safe: true });
  console.log(c.checkPrimeSync(sp), Buffer.from(sp).readUInt32BE(0) % 4);
  const q: any = c.generatePrimeSync(40, { add: Buffer.from([16]), rem: Buffer.from([5]) });
  console.log(Buffer.from(q)[4] % 16, c.checkPrimeSync(q));
  await new Promise<void>((r) => c.generatePrime(24, (e: any, v: any) => { console.log(e, typeof v, v.byteLength); r(); }));
  for (const bad of [() => c.checkPrimeSync('x'), () => c.generatePrimeSync(0), () => c.checkPrime(Buffer.from([7]))]) {
    try { bad(); } catch (e: any) { console.log(e.code, e.message); }
  }
  const a: any = c.getDiffieHellman('modp5');
  const b: any = c.createDiffieHellmanGroup('modp5');
  a.generateKeys(); b.generateKeys();
  console.log(a.computeSecret(b.getPublicKey()).equals(b.computeSecret(a.getPublicKey())), a.getPrime('hex').length, a.getGenerator('hex'), a.verifyError);
  const d: any = c.createDiffieHellman(a.getPrime(), 'buffer', 5);
  console.log(d.getGenerator('hex'), typeof d.verifyError);
  try { c.getDiffieHellman('nope'); } catch (e: any) { console.log(e.code, e.message); }
  console.log(JSON.stringify(c.getCipherInfo('aes-128-cbc')), JSON.stringify(c.getCipherInfo('aes-256-gcm')), JSON.stringify(c.getCipherInfo(419)), c.getCipherInfo('nope'), c.getCipherInfo('aes-128-cbc', { keyLength: 15 }));
  console.log(c.generateKeySync('aes', { length: 192 }).export().length, c.generateKeySync('hmac', { length: 64 }).type);
  await new Promise<void>((r) => c.generateKey('hmac', { length: 128 }, (e: any, k: any) => { console.log(e, k.symmetricKeySize); r(); }));
}
